package cl.skinspad.usuario;
import org.junit.jupiter.api.Test;import org.springframework.beans.factory.annotation.Autowired;import org.springframework.boot.test.context.SpringBootTest;import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;import org.springframework.test.web.servlet.MockMvc;import org.springframework.http.MediaType;import static org.junit.jupiter.api.Assertions.*;import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.*;import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.*;
@SpringBootTest(properties={"spring.datasource.url=jdbc:h2:mem:moderacionusuario;MODE=MySQL;DB_CLOSE_DELAY=-1","spring.datasource.driver-class-name=org.h2.Driver","spring.jpa.hibernate.ddl-auto=create-drop"}) @AutoConfigureMockMvc
class ModeracionReporteTest {
 @Autowired MockMvc mvc;@Autowired cl.skinspad.usuario.config.InternalApiKey key;@Autowired cl.skinspad.usuario.repository.UsuarioRepository usuarios;@Autowired cl.skinspad.usuario.moderacion.AccionReporteRepository acciones;
 @Test void suspenderRepiteSinDuplicarYNoPermiteActorCliente()throws Exception{String url="/api/internal/moderacion/usuarios/u3/suspender",body="{\"referencia\":\"REP-1-ok\",\"actor\":\"u2\",\"motivo\":\"Moderación de soporte\"}";mvc.perform(post(url).contentType(MediaType.APPLICATION_JSON).content(body)).andExpect(status().isForbidden());mvc.perform(post(url).header("X-Skins-Internal",key.value()).contentType(MediaType.APPLICATION_JSON).content(body.replace("u2","u1"))).andExpect(status().isForbidden());for(int i=0;i<2;i++)mvc.perform(post(url).header("X-Skins-Internal",key.value()).contentType(MediaType.APPLICATION_JSON).content(body)).andExpect(status().isOk());assertTrue(usuarios.findById("u3").orElseThrow().isSuspendido());assertEquals(1,acciones.count());}
}
